export type AgentRequest = {
  readonly id: RequestId;
  readonly method: string;
  readonly params?:
    | WriteTextFileRequest
    | ReadTextFileRequest
    | RequestPermissionRequest
    | CreateTerminalRequest
    | TerminalOutputRequest
    | ReleaseTerminalRequest
    | WaitForTerminalExitRequest
    | KillTerminalRequest
    | CreateElicitationRequest
    | MessageMcpRequest
    | ExtRequest
    | null;
};
export const AgentRequest = Schema.Struct({
  id: Schema.suspend((): Schema.Codec<RequestId> => RequestId).annotate({
    description: "The request id used to correlate the matching response.",
  }),
  method: Schema.String.annotate({ description: "The method name to invoke." }),
  params: Schema.optionalKey(
    Schema.Union([
      Schema.Union([
        Schema.suspend((): Schema.Codec<WriteTextFileRequest> => WriteTextFileRequest).annotate({
          title: "WriteTextFileRequest",
          description:
            "Writes content to a text file in the client's file system.\n\nOnly available if the client advertises the `fs.writeTextFile` capability.\nAllows the agent to create or modify files within the client's environment.\n\nSee protocol docs: [Client](https://agentclientprotocol.com/protocol/v1/draft/overview#client)",
        }),
        Schema.suspend((): Schema.Codec<ReadTextFileRequest> => ReadTextFileRequest).annotate({
          title: "ReadTextFileRequest",
          description:
            "Reads content from a text file in the client's file system.\n\nOnly available if the client advertises the `fs.readTextFile` capability.\nAllows the agent to access file contents within the client's environment.\n\nSee protocol docs: [Client](https://agentclientprotocol.com/protocol/v1/draft/overview#client)",
        }),
        Schema.suspend(
          (): Schema.Codec<RequestPermissionRequest> => RequestPermissionRequest,
        ).annotate({
          title: "RequestPermissionRequest",
          description:
            "Requests permission from the user for a tool call operation.\n\nCalled by the agent when it needs user authorization before executing\na potentially sensitive operation. The client should present the options\nto the user and return their decision.\n\nIf the client cancels the prompt turn via `session/cancel`, it MUST\nrespond to this request with the `cancelled` outcome.\n\nSee protocol docs: [Requesting Permission](https://agentclientprotocol.com/protocol/v1/draft/tool-calls#requesting-permission)",
        }),
        Schema.suspend((): Schema.Codec<CreateTerminalRequest> => CreateTerminalRequest).annotate({
          title: "CreateTerminalRequest",
          description:
            "Executes a command in a new terminal\n\nOnly available if the `terminal` Client capability is set to `true`.\n\nReturns a `TerminalId` that can be used with other terminal methods\nto get the current output, wait for exit, and kill the command.\n\nThe `TerminalId` can also be used to embed the terminal in a tool call\nby using `terminal` tool call content.\n\nThe Agent is responsible for releasing the terminal by using the `terminal/release`\nmethod.\n\nSee protocol docs: [Terminals](https://agentclientprotocol.com/protocol/v1/draft/terminals)",
        }),
        Schema.suspend((): Schema.Codec<TerminalOutputRequest> => TerminalOutputRequest).annotate({
          title: "TerminalOutputRequest",
          description:
            "Gets the terminal output and exit status\n\nReturns the current content in the terminal without waiting for the command to exit.\nIf the command has already exited, the exit status is included.\n\nSee protocol docs: [Terminals](https://agentclientprotocol.com/protocol/v1/draft/terminals)",
        }),
        Schema.suspend((): Schema.Codec<ReleaseTerminalRequest> => ReleaseTerminalRequest).annotate(
          {
            title: "ReleaseTerminalRequest",
            description:
              "Releases a terminal\n\nThe command is killed if it hasn't exited yet. Use `terminal/wait_for_exit`\nto wait for the command to exit before releasing the terminal.\n\nAfter release, the `TerminalId` can no longer be used with other `terminal/*` methods,\nbut tool calls that already contain it, continue to display its output.\n\nThe `terminal/kill` method can be used to terminate the command without releasing\nthe terminal, allowing the Agent to call `terminal/output` and other methods.\n\nSee protocol docs: [Terminals](https://agentclientprotocol.com/protocol/v1/draft/terminals)",
          },
        ),
        Schema.suspend(
          (): Schema.Codec<WaitForTerminalExitRequest> => WaitForTerminalExitRequest,
        ).annotate({
          title: "WaitForTerminalExitRequest",
          description:
            "Waits for the terminal command to exit and return its exit status\n\nSee protocol docs: [Terminals](https://agentclientprotocol.com/protocol/v1/draft/terminals)",
        }),
        Schema.suspend((): Schema.Codec<KillTerminalRequest> => KillTerminalRequest).annotate({
          title: "KillTerminalRequest",
          description:
            "Kills the terminal command without releasing the terminal\n\nWhile `terminal/release` will also kill the command, this method will keep\nthe `TerminalId` valid so it can be used with other methods.\n\nThis method can be helpful when implementing command timeouts which terminate\nthe command as soon as elapsed, and then get the final output so it can be sent\nto the model.\n\nNote: Call `terminal/release` when `TerminalId` is no longer needed.\n\nSee protocol docs: [Terminals](https://agentclientprotocol.com/protocol/v1/draft/terminals)",
        }),
        Schema.suspend(
          (): Schema.Codec<CreateElicitationRequest> => CreateElicitationRequest,
        ).annotate({
          title: "CreateElicitationRequest",
          description:
            "Requests structured user input via a form or URL.\n\nSee protocol docs: [Elicitation](https://agentclientprotocol.com/protocol/v1/draft/elicitation)",
        }),
        Schema.suspend((): Schema.Codec<MessageMcpRequest> => MessageMcpRequest).annotate({
          title: "MessageMcpRequest",
          description:
            "**UNSTABLE**\n\nThis capability is not part of the spec yet, and may be removed or changed at any point.\n\nExchanges an MCP-over-ACP message.",
        }),
        Schema.suspend((): Schema.Codec<ExtRequest> => ExtRequest).annotate({
          title: "ExtMethodRequest",
          description:
            "Handles extension method requests from the agent.\n\nAllows the Agent to send an arbitrary request that is not part of the ACP spec.\nExtension methods provide a way to add custom functionality while maintaining\nprotocol compatibility.\n\nSee protocol docs: [Extensibility](https://agentclientprotocol.com/protocol/v1/draft/extensibility)",
        }),
      ]).annotate({
        description:
          "All possible requests that an agent can send to a client.\n\nThis enum is used internally for routing RPC requests. You typically won't need\nto use this directly.\n\nThis enum encompasses all method calls from agent to client.",
      }),
      Schema.Null,
    ]).annotate({ description: "Method-specific request parameters." }),
  ),
}).annotate({ description: "A JSON-RPC request object." });

